{
  "items": [
    {
      "name": "Rat.finite_rat_abs_sub_lt_one_div_den_sq",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ (ξ : ℚ), {q | |ξ - q| < 1 / ↑q.den ^ 2}.Finite"
    },
    {
      "name": "Real.infinite_rat_abs_sub_lt_one_div_den_sq_of_irrational",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ {ξ : ℝ}, Irrational ξ → {q | |ξ - ↑q| < 1 / ↑q.den ^ 2}.Infinite"
    },
    {
      "name": "Rat.den_le_and_le_num_le_of_sub_lt_one_div_den_sq",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ {ξ q : ℚ}, |ξ - q| < 1 / ↑q.den ^ 2 → q.den ≤ ξ.den ∧ ⌈ξ * ↑q.den⌉ - 1 ≤ q.num ∧ q.num ≤ ⌊ξ * ↑q.den⌋ + 1"
    },
    {
      "name": "Real.infinite_rat_abs_sub_lt_one_div_den_sq_iff_irrational",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ (ξ : ℝ), {q | |ξ - ↑q| < 1 / ↑q.den ^ 2}.Infinite ↔ Irrational ξ"
    },
    {
      "name": "Real.exists_rat_eq_convergent",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ {ξ : ℝ} {q : ℚ}, |ξ - ↑q| < 1 / (2 * ↑q.den ^ 2) → ∃ n, q = ξ.convergent n"
    },
    {
      "name": "Real.exists_rat_abs_sub_le_and_den_le",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ (ξ : ℝ) {n : ℕ}, 0 < n → ∃ q, |ξ - ↑q| ≤ 1 / ((↑n + 1) * ↑q.den) ∧ q.den ≤ n"
    },
    {
      "name": "Real.exists_rat_abs_sub_lt_and_lt_of_irrational",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ {ξ : ℝ}, Irrational ξ → ∀ (q : ℚ), ∃ q', |ξ - ↑q'| < 1 / ↑q'.den ^ 2 ∧ |ξ - ↑q'| < |ξ - ↑q|"
    },
    {
      "name": "Real.exists_convs_eq_rat",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.ContinuedFractions",
      "kind": "theorem",
      "type": "∀ {ξ : ℝ} {q : ℚ}, |ξ - ↑q| < 1 / (2 * ↑q.den ^ 2) → ∃ n, (GenContFract.of ξ).convs n = ↑q"
    }
  ]
}
